// The Worker entry: the www redirect and the OpenNext app for requests, plus the hourly Cron
// Trigger that rebuilds the site (docs/product.md §14 item 2). See the OpenNext "custom worker" guide.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore .open-next/worker.js is generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";
import { canonicalRedirect } from "./src/lib/canonical-host";
import { triggerRebuild, type RebuildEnv } from "./src/lib/rebuild";

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    return canonicalRedirect(request) ?? handler.fetch(request, env, ctx);
  },

  async scheduled(_controller: unknown, env: RebuildEnv, ctx: { waitUntil(promise: Promise<unknown>): void }) {
    ctx.waitUntil(triggerRebuild(env).then((result) => console.log(`Hourly rebuild: ${result}`)));
  },
};

export default worker;
